/**
 * Shape of a single entry in the client-side tools index.
 *
 * The index itself is generated by `src/scripts/generate-tools-index.mjs`
 * from `src/data/geo-matrix.json`. This type exists so the search
 * components do not have to reach into an untyped JSON import.
 */
export interface ToolIndexEntry {
  title: string;
  shortTitle: string;
  category: string;
  slug: string;
  subtitle: string;
  href: string;
  jurisdictionCode?: string;
  stateName?: string;
  rate?: number;
  badge?: string;
}
